<script setup lang="ts">
import { onMounted, ref } from 'vue'
import FilePicker from '@/components/FilePicker.vue'
import { demoMode, httpErrorMessage, readResponseJson, request as liveRequest, serviceUnavailable } from '@/services/quality'
import { boardRequest } from '@/services/cdcBoardsDemo'
const request = demoMode ? boardRequest : liveRequest

type Doc = { id:number; title:string; kind:string; process?:string; status:string; version:number; content:string; sha256:string }
type Source = { id:number; source_kind:string; original_name:string; sha256:string; provenance:string; status:string; document_code?:string; document_kind?:string }
type Template = { id:number; name:string; version:number; status:string; fields:string; sha256:string }
const rows=ref<Doc[]>([]), sources=ref<Source[]>([]), templates=ref<Template[]>([]), title=ref(''), kind=ref('procedure'), process=ref(''), content=ref(''), error=ref(''), loading=ref(false)
const availability=ref<{available:boolean;message:string|null}>({available:false,message:'État non vérifié.'})
const file=ref<File|null>(null), provenance=ref(''), sourceKind=ref('corpus'), followupType=ref('formations'), followupTheme=ref(''),
  attachmentFiles=ref<Record<number,File|null>>({}),
  templateName=ref(''), fieldKey=ref('objectif'), fieldLabel=ref('Objectif'),
  password=ref(''), qualificationNote=ref('Vérification humaine du document source.'), documentCode=ref('A-QUALIFIER'),
  values=ref<Record<string,string>>({})
const base='/documents/library'
async function load(){loading.value=true;error.value='';try{const [docs,src,tpl,state]=await Promise.all([
  request<{data:{data:Doc[]}}>('/documents'),request<{data:{data:Source[]}}>(`${base}/sources`),
  request<{data:{data:Template[]}}>(`${base}/templates`),request<typeof availability.value>(`${base}/status`)
]);rows.value=docs.data.data;sources.value=src.data.data;templates.value=tpl.data.data;availability.value=state}catch(e){error.value=e instanceof Error?e.message:'Chargement GED impossible.'}finally{loading.value=false}}
async function create(){error.value='';try{await request('/documents','POST',{title:title.value,kind:kind.value,process:process.value,content:content.value});title.value='';content.value='';await load()}catch(e){error.value=e instanceof Error?e.message:'Enregistrement impossible.'}}
async function submit(d:Doc){error.value='';try{await request(`/documents/${d.id}/submit`,'POST',{version:d.version});await load()}catch(e){error.value=e instanceof Error?e.message:'Soumission impossible.'}}
async function approveDocument(d:Doc){error.value='';try{await request(`/documents/${d.id}/approve`,'POST',{version:d.version,sha256:d.sha256,password:password.value});password.value='';await load()}catch(e){error.value=e instanceof Error?e.message:'Approbation refusée.'}}
async function reviseDocument(d:Doc){error.value='';try{await request(`/documents/${d.id}/revisions`,'POST',{version:d.version});await load()}catch(e){error.value=e instanceof Error?e.message:'Nouvelle révision impossible.'}}
async function uploadAttachment(d:Doc){const picked=attachmentFiles.value[d.id];if(!picked)return;error.value='';try{const body=new FormData();body.append('file',picked);body.append('version',String(d.version));let response:Response;try{response=await fetch(`/api/v1/documents/${d.id}/attachments`,{method:'POST',headers:{Accept:'application/json',Authorization:`Bearer ${sessionStorage.getItem('bestpharma.token')||''}`,'X-Officine-ID':sessionStorage.getItem('bestpharma.officine')||''},body})}catch{throw Error(serviceUnavailable)}const data=await readResponseJson(response);if(!response.ok)throw Error(httpErrorMessage(response,data,'Pièce jointe refusée.'));attachmentFiles.value[d.id]=null;await load()}catch(e){error.value=e instanceof Error?e.message:'Pièce jointe refusée.'}}
async function importFile(){if(!file.value)return;error.value='';try{const body=new FormData();body.append('file',file.value);body.append('source_kind',sourceKind.value);body.append('provenance',provenance.value);let response:Response;try{response=await fetch('/api/v1'+base+'/sources/import',{method:'POST',headers:{Accept:'application/json',Authorization:`Bearer ${sessionStorage.getItem('bestpharma.token')||''}`,'X-Officine-ID':sessionStorage.getItem('bestpharma.officine')||''},body})}catch{throw Error(serviceUnavailable)}const result=await readResponseJson(response);if(!response.ok)throw Error(httpErrorMessage(response,result,'Import refusé.'));file.value=null;provenance.value='';await load()}catch(e){error.value=e instanceof Error?e.message:'Import indisponible.'}}
async function downloadSource(s:Source){error.value='';try{let response:Response;try{response=await fetch(`/api/v1${base}/sources/${s.id}/file`,{headers:{Authorization:`Bearer ${sessionStorage.getItem('bestpharma.token')||''}`,'X-Officine-ID':sessionStorage.getItem('bestpharma.officine')||''}})}catch{throw Error(serviceUnavailable)}if(!response.ok){const data=await readResponseJson(response);throw Error(httpErrorMessage(response,data,'Source inaccessible.'))}const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=s.original_name;a.click();URL.revokeObjectURL(url)}catch(e){error.value=e instanceof Error?e.message:'Source inaccessible.'}}
async function qualify(s:Source){error.value='';try{await request(`${base}/sources/${s.id}/qualify`,'POST',{document_code:documentCode.value,document_kind:'procedure',process:'QAM',qualification_note:qualificationNote.value});await load()}catch(e){error.value=e instanceof Error?e.message:'Qualification refusée.'}}
async function approveSource(s:Source){error.value='';try{await request(`${base}/sources/${s.id}/approve`,'POST',{sha256:s.sha256,password:password.value,confirmed:true});password.value='';await load()}catch(e){error.value=e instanceof Error?e.message:'Approbation refusée.'}}
async function createTemplate(s:Source){error.value='';try{await request(`${base}/templates`,'POST',{source_id:s.id,name:templateName.value||s.document_code||s.original_name,fields:[{key:fieldKey.value,label:fieldLabel.value,type:'text'}]});await load()}catch(e){error.value=e instanceof Error?e.message:'Création du canevas refusée.'}}
async function approveTemplate(t:Template){error.value='';try{await request(`${base}/templates/${t.id}/approve`,'POST',{sha256:t.sha256,password:password.value,confirmed:true});password.value='';await load()}catch(e){error.value=e instanceof Error?e.message:'Approbation du canevas refusée.'}}
async function instantiate(t:Template){error.value='';try{await request(`${base}/templates/${t.id}/instances`,'POST',{values:{[fieldKey.value]:values.value[fieldKey.value]||''}});await load()}catch(e){error.value=e instanceof Error?e.message:'Instanciation refusée.'}}
async function createFollowup(){error.value='';try{const data=followupType.value==='formations'?{theme:followupTheme.value,responsable_suivi:'À désigner'}:{nature:followupTheme.value,responsable_suivi:'À désigner'};await request(`${base}/followups/${followupType.value}`,'POST',{status:'planned',data});followupTheme.value='';await load()}catch(e){error.value=e instanceof Error?e.message:'Suivi non enregistré.'}}
onMounted(load)
</script>
<template><div class="page"><div class="page-heading"><div><p class="eyebrow">DOCUMENTS · ESPACE PRIVÉ PAR OFFICINE</p><h1>Documents, canevas & imports</h1><p class="page-subtitle">Les imports restent privés et en quarantaine. Une qualification puis une approbation humaine distinctes sont nécessaires.</p></div></div>
<p v-if="error" class="alert error" role="alert">{{error}}</p>
<section class="panel"><h2>Import de corpus / référentiel BPD</h2><p>Les fichiers déposés ne sont ni extraits automatiquement, ni déclarés ABMed ou validés. SHA-256 et provenance sont conservés.</p><form class="form-body" @submit.prevent="importFile"><label>Lot<select v-model="sourceKind"><option value="corpus">Corpus documentaire</option><option value="bpd">Référentiel BPD · à relire</option></select></label><label>Provenance vérifiable<input v-model="provenance" required minlength="8" maxlength="500" placeholder="Origine, date, opérateur, référence…" /></label><label>Fichier<FilePicker v-model="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.odt,.ods,.csv,.txt,.json" /></label><button class="button primary" :disabled="loading||!file">Importer en quarantaine</button></form></section>
<section class="panel"><h2>Qualification humaine des sources</h2><p v-if="!sources.length" class="empty-state">Aucune source importée dans cette officine. Aucun corpus historique n’a été importé automatiquement.</p><article v-for="s in sources" :key="s.id" class="document-row"><div><strong>{{s.original_name}}</strong><p>{{s.source_kind==='bpd'?'Référentiel BPD':'Corpus'}} · {{s.status}} · {{s.provenance}}</p><small>SHA-256 {{s.sha256}}</small><button class="button secondary" @click="downloadSource(s)">Télécharger pour examen</button></div><div class="form-body"><template v-if="s.status==='quarantine'"><label>Code documentaire vérifié<input v-model="documentCode" /></label><label>Motif de qualification<input v-model="qualificationNote" /></label><button class="button secondary" @click="qualify(s)">Qualifier après examen</button></template><template v-else-if="s.status==='qualified'"><label>Mot de passe de confirmation<input v-model="password" type="password" autocomplete="current-password" /></label><button class="button secondary" @click="approveSource(s)">Approuver explicitement cette source</button></template><template v-else><label>Nom du canevas<input v-model="templateName" :placeholder="s.document_code" /></label><button class="button secondary" @click="createTemplate(s)">Créer un canevas brouillon depuis cette source</button></template></div></article></section>
<section class="panel"><h2>Canevas versionnés</h2><p v-if="!templates.length" class="empty-state">Aucun canevas. Les canevas ne peuvent être créés qu’à partir d’une source approuvée.</p><article v-for="t in templates" :key="t.id" class="document-row"><div><strong>{{t.name}}</strong><p>v{{t.version}} · {{t.status}} · empreinte {{t.sha256}}</p></div><div class="form-body"><template v-if="t.status==='draft'"><label>Mot de passe de confirmation<input v-model="password" type="password" autocomplete="current-password" /></label><button class="button secondary" @click="approveTemplate(t)">Approuver cette version immuable</button></template><template v-else><label>Valeur de {{fieldLabel}}<input v-model="values[fieldKey]" /></label><button class="button primary" @click="instantiate(t)">Créer un enregistrement brouillon</button></template></div></article><p v-if="!availability.available" class="alert">{{availability.message}}</p></section>
<section class="panel"><h2>Suivis documentaires</h2><form class="form-body" @submit.prevent="createFollowup"><label>Registre<select v-model="followupType"><option value="formations">Formation</option><option value="maintenance">Maintenance</option></select></label><label>{{followupType==='formations'?'Thème':'Nature de maintenance'}}<input v-model="followupTheme" required /></label><button class="button secondary">Enregistrer un suivi planifié</button></form></section>
<section class="panel"><h2>Documents de l’officine</h2><form class="form-body" @submit.prevent="create"><label>Titre<input v-model="title" required maxlength="255" /></label><label>Type<select v-model="kind"><option value="procedure">Procédure</option><option value="mop">Mode opératoire</option><option value="form">Formulaire / canevas</option><option value="record">Enregistrement</option></select></label><label>Processus<input v-model="process" maxlength="80" /></label><label>Contenu du brouillon<textarea v-model="content" rows="5" maxlength="100000" /></label><button class="button primary" :disabled="loading">Enregistrer en brouillon</button></form></section>
 <section class="panel"><h2>Inventaire</h2><p v-if="loading">Chargement…</p><p v-else-if="!rows.length" class="empty-state">Aucun document. Les exemples historiques ne sont pas importés ; aucune source n’est considérée comme approuvée.</p><article v-for="d in rows" :key="d.id" class="document-row"><div><strong>{{d.title}}</strong><p>{{d.kind}} · {{d.process||'Sans processus'}} · v{{d.version}} · {{d.status}}</p><small>SHA-256 {{d.sha256}}</small><div v-if="d.status==='draft'" class="form-body"><label>Pièce jointe privée<input type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.odt,.jpg,.jpeg,.png" @change="attachmentFiles[d.id]=($event.target as HTMLInputElement).files?.[0]||null"></label><button class="button secondary" :disabled="!attachmentFiles[d.id]" @click="uploadAttachment(d)">Joindre à cette version brouillon</button></div></div><div class="heading-actions"><button v-if="d.status==='draft'" class="button secondary" @click="submit(d)">Soumettre pour approbation</button><template v-if="d.status==='pending'"><label>Mot de passe de confirmation<input v-model="password" type="password" autocomplete="current-password"></label><button class="button primary" @click="approveDocument(d)">Approuver cette version exacte</button></template><button v-if="d.status==='approved'" class="button secondary" @click="reviseDocument(d)">Créer une nouvelle révision</button></div></article></section><p class="muted-note">Les suivis ne valent ni preuve de compétence ni certificat. Aucune transmission ABMed, conformité réglementaire ou validation n’est affirmée sans preuve.</p></div></template>
